  const r = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body.items, [{ sku: 'A', qty: 2 }])
  assert.equal(r.body.total, 20)
  assert.deepEqual(Object.keys(r.body).sort(), ['id', 'items', 'total'])
})

test('ids are sequential strings', async () => {
  const a = await post({ items: [{ sku: 'A', qty: 1 }] })
  const b = await post({ items: [{ sku: 'A', qty: 1 }] })
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('total sums across items', async () => {
  const r = await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }] })
  assert.equal(r.body.total, 61)
})

test('total is floored to a whole number (no cents)', async () => {
  const r = await post({ items: [{ sku: 'B', qty: 1 }] })
  assert.equal(r.body.total, 25)
  assert.equal((await post({ items: [{ sku: 'D', qty: 1 }] })).body.total, 0)
})

test('no discount at exactly 100', async () => {
  const r = await post({ items: [{ sku: 'A', qty: 10 }] })
  assert.equal(r.body.total, 100)
})

