  for (const body of [{}, { items: [] }, { items: 'A' }, { items: null }]) {
    const r = await post(body)
    assert.equal(r.status, 400)
    assert.deepEqual(r.body, { error: 'items required' })
  }
})

test('rejects malformed JSON with 400', async () => {
  const r = await post(undefined, '{nope')
  assert.equal(r.status, 400)
  assert.deepEqual(r.body, { error: 'items required' })
})

test('empty body is treated as {} and rejected with 400', async () => {
  const r = await post(undefined, '')
  assert.equal(r.status, 400)
})

test('unknown sku / bad qty are not validated: total becomes null (NaN serialised)', async () => {
  const r = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('negative qty is accepted and yields a negative total', async () => {
  const r = await post({ items: [{ sku: 'A', qty: -1 }] })
  assert.equal(r.status, 201)
  assert.equal(r.body.total, -10)
})

